        return value
    try:
        return date.fromisoformat(str(value).strip())
    except ValueError:
        raise ValueError(f"not a service day: {value!r}")


def parse_clock(value):
    if value is None:
        raise ValueError("missing clock")
    text = str(value).strip()
    for pattern in ("%H:%M:%S", "%H:%M"):
        try:
            return datetime.strptime(text, pattern).time()
        except ValueError:
            continue
    raise ValueError(f"not a clock time: {value!r}")


def channel_set(value):
    """`CD` / `C,D` / ['C','D'] -> {'C','D'}; None/empty -> None (all channels)."""
    if value is None or value == "":
        return None
    if isinstance(value, (list, tuple, set)):
        text = "".join(str(item) for item in value)
    else:
        text = str(value)
    letters = {char for char in text.upper() if char in CHANNEL_ALPHABET}
    return letters or None


def channel_in(channels, channel):
    if not channels:                        # authorisation covers every channel
        return True
    return str(channel).upper() in channels


def normalise_series(entry):
    code = str(entry.get("code", "")).strip()
    if not code:
        raise ValueError(f"portfolio entry without code: {entry!r}")
    zone = str(entry.get("zone", "")).strip()
    ZoneInfo(zone)                                    # unknown zone fails loudly
    basis = str(entry.get("basis", "wall")).strip().lower()
    if basis not in BASES:
        raise ValueError(f"{code}: unknown basis {entry.get('basis')!r}")
    clock = str(entry.get("clock", "")).strip()
    parse_clock(clock)
    weekday = int(entry.get("weekday", 0))
    if not 0 <= weekday <= 6:
        raise ValueError(f"{code}: weekday out of range: {weekday}")
    return dict(code=code, sid=entry.get("sid"), zone=zone, clock=clock,
                basis=basis, weekday=weekday)


def _window(row):
    """Original-service-day window from start/end, a single day, or nothing."""
    single = row.get("day", row.get("original_day", row.get("date")))
    start = row.get("start", row.get("from", single))
    end = row.get("end", row.get("to", single))
    return as_day(start), as_day(end)


def normalise_order(row, version):
    oid = str(row.get("id", "")).strip()
    if not oid:
        raise ValueError(f"order row without an immutable id: {row!r}")
    target = row.get("target")
    target = str(target).strip() if target not in (None, "") else None
    word = str(row.get("kind", "")).strip().lower()
    kind = KIND_REVOKE if (target or word in REVOKE_WORDS) else KIND_APPROVAL
    if kind == KIND_REVOKE and not target:
        raise ValueError(f"{oid}: a revocation must name a target")
    code = row.get("code")
    code = str(code).strip() if code not in (None, "") else None
    if kind == KIND_APPROVAL and not code:
        raise ValueError(f"{oid}: an approval must name a code")
    start_day, end_day = _window(row)
    clock = row.get("clock")
    if clock not in (None, ""):
        parse_clock(clock)
        clock = str(clock).strip()
    else:
        clock = None
    basis = row.get("basis")
    if basis not in (None, ""):
        basis = str(basis).strip().lower()
        if basis not in BASES:
            raise ValueError(f"{oid}: unknown basis {row.get('basis')!r}")
    else:
        basis = None
    return dict(id=oid, version=int(version), kind=kind, code=code,
                channels=channel_set(row.get("channels")),
                start_day=start_day.isoformat() if start_day else None,
                end_day=end_day.isoformat() if end_day else None,
                rank=int(row.get("rank") or 0), clock=clock, basis=basis,
                shift_days=int(row.get("shift_days") or 0), target=target)


def _stored_channels(text):
    if not text:
        return None
    return set(text)


# --------------------------------------------------------------------------- #
# import
# --------------------------------------------------------------------------- #
def _portfolio_path(input_dir):
    for candidate in (os.path.join(input_dir, "portfolio.json"),
                      os.path.join(os.path.dirname(os.path.abspath(input_dir)), "portfolio.json")):
        if os.path.exists(candidate):
            return candidate
    raise ValueError(f"no portfolio.json in {input_dir}")


def _order_files(input_dir):
    orders_dir = os.path.join(input_dir, "orders")
    if os.path.isdir(orders_dir):
        return sorted(glob.glob(os.path.join(orders_dir, "*.json"))), orders_dir
