        return sorted(path for path in glob.glob(os.path.join(input_dir, "*.json"))
                      if os.path.basename(path) != "portfolio.json"), input_dir
    return [], orders_dir


def _same(current, wanted, columns):
    return all(current[column] == wanted[column] for column in columns)


def import_dir(db, input_dir, stamp=None):
    """Incrementally register portfolio + order batches; -> report dict."""
    ensure_schema(db)
    stamp = stamp if stamp is not None else business_day()
    report = {"portfolio": [], "orders": []}
    try:
        with open(_portfolio_path(input_dir), encoding="utf-8") as handle:
            entries = json.load(handle)
        if not isinstance(entries, list):
            raise ValueError("portfolio.json must be a JSON list")
        for entry in entries:
            wanted = normalise_series(entry)
            current = db.execute("select " + ",".join(SERIES_COLUMNS)
                                 + " from line_series where code=?", (wanted["code"],)).fetchone()
            if current is None:
                db.execute("insert into line_series(" + ",".join(SERIES_COLUMNS) + ",imported) values("
                           + ",".join("?" * (len(SERIES_COLUMNS) + 1)) + ")",
                           tuple(wanted[column] for column in SERIES_COLUMNS) + (stamp,))
                action = "imported"
            elif _same(dict(zip(SERIES_COLUMNS, current)), wanted, SERIES_COLUMNS):
                action = "unchanged"
            else:
                db.execute("update line_series set sid=?,zone=?,clock=?,basis=?,weekday=? where code=?",
                           (wanted["sid"], wanted["zone"], wanted["clock"],
                            wanted["basis"], wanted["weekday"], wanted["code"]))
                action = "updated"
            report["portfolio"].append(dict(code=wanted["code"], action=action))

        files, _ = _order_files(input_dir)
        seen_here = set()
        for path in files:
            with open(path, encoding="utf-8") as handle:
                batch = json.load(handle)
            if not isinstance(batch, dict) or "version" not in batch or "rows" not in batch:
                raise ValueError(f"{path}: an order file needs version and rows")
            version = int(batch["version"])
            if not isinstance(batch["rows"], list):
                raise ValueError(f"{path}: rows must be a list")
            for row in batch["rows"]:
                wanted = normalise_order(row, version)
                current = db.execute("select " + ",".join(ORDER_COLUMNS)
                                     + " from line_order where id=?", (wanted["id"],)).fetchone()
                if current is not None:
                    if not _same(dict(zip(ORDER_COLUMNS, current)), wanted, ORDER_COLUMNS):
                        raise ValueError(f'{wanted["id"]}: immutable id re-sent with different content')
                    action = "duplicate"
                elif wanted["id"] in seen_here:
                    action = "duplicate"
                else:
                    db.execute("insert into line_order(" + ",".join(ORDER_COLUMNS) + ",imported) values("
                               + ",".join("?" * (len(ORDER_COLUMNS) + 1)) + ")",
                               tuple(wanted[column] for column in ORDER_COLUMNS) + (stamp,))
                    action = "imported"
                seen_here.add(wanted["id"])
                report["orders"].append(dict(id=wanted["id"], version=version,
                                             code=wanted["code"], kind=wanted["kind"],
                                             action=action))
        db.commit()
    except Exception:
        db.rollback()
        raise
    return report


# --------------------------------------------------------------------------- #
# query
# --------------------------------------------------------------------------- #
def _series(db):
    return [dict(zip(SERIES_COLUMNS, row)) for row in
            db.execute("select " + ",".join(SERIES_COLUMNS) + " from line_series order by code")]


def _orders(db):
    return [dict(zip(ORDER_COLUMNS, row)) for row in
            db.execute("select " + ",".join(ORDER_COLUMNS) + " from line_order order by id")]


def _approved(order, day):
    if order["start_day"] and day < date.fromisoformat(order["start_day"]):
        return False
    if order["end_day"] and day > date.fromisoformat(order["end_day"]):
        return False
    return True


def _revoked(approval, day, channel, revokes):
    for revoke in revokes:
        if revoke["target"] != approval["id"]:
            continue
        if not channel_in(revoke["channels"], channel):
            continue
        if revoke["start_day"] and day < date.fromisoformat(revoke["start_day"]):
            continue
        if revoke["end_day"] and day > date.fromisoformat(revoke["end_day"]):
            continue
        return True
    return False


def to_utc(day, clock, basis, zone):
    """A service day plus a clock -> an aware UTC instant."""
    moment = parse_clock(clock)
    if basis == "utc":
        return datetime.combine(day, moment, tzinfo=timezone.utc)
    if basis == "wall":
        return datetime.combine(day, moment, tzinfo=ZoneInfo(zone)).astimezone(timezone.utc)
    raise ValueError(f"unknown basis {basis!r}")


def _first_day(start, weekday):
    """First `weekday` on or after max(start, BASE_START)."""
    floor = start if start > BASE_START else BASE_START
    return floor + timedelta(days=(weekday - floor.weekday()) % 7)


def query(db, channel, start, end, asof):
    """-> [{code, day, utc}] for a channel over original Monday service days."""
    channel = str(channel).strip().upper()
    start, end, asof = as_day(start), as_day(end), int(asof)
    if start is None or end is None or start > end:
        return []
    try:
        series = _series(db)
        registered = _orders(db)
    except sqlite3.OperationalError:          # database never imported
        return []
    by_id = {order["id"]: order for order in registered}
    approvals = [order for order in registered
                 if order["kind"] == KIND_APPROVAL and order["version"] <= asof]
    revokes = [order for order in registered
               if order["kind"] == KIND_REVOKE and order["version"] <= asof]

    rows = []
    for item in series:
        day = _first_day(start, item["weekday"])
        while day <= end:
            candidates = [order for order in approvals
                          if order["code"] == item["code"]
                          and channel_in(order["channels"], channel)
                          and _approved(order, day)]
            candidates.sort(key=lambda order: (order["rank"], order["version"], order["id"]),
                            reverse=True)
            chosen = next((order for order in candidates
                           if not _revoked(order, day, channel, revokes)), None)
            if chosen is not None:
                service_day = day + timedelta(days=chosen["shift_days"])
                clock = chosen["clock"] or item["clock"]
                basis = chosen["basis"] or item["basis"]
            else:
                service_day = day
                clock, basis = item["clock"], item["basis"]
            moment = to_utc(service_day, clock, basis, item["zone"])
            rows.append((day, item["code"],
                         dict(code=item["code"], day=service_day.isoformat(),
                              utc=moment.astimezone(timezone.utc).isoformat())))
            day += timedelta(days=7)
    rows.sort(key=lambda entry: (entry[0], entry[1]))   # business day, then code
    return [row for _, _, row in rows]


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #
def main(argv=None):
    parser = argparse.ArgumentParser(prog="line.py")
    sub = parser.add_subparsers(dest="action", required=True)
    importer = sub.add_parser("import")
    importer.add_argument("input_dir")
    asker = sub.add_parser("query")
    asker.add_argument("channel")
    asker.add_argument("start")
    asker.add_argument("end")
    asker.add_argument("asof", type=int)
    args = parser.parse_args(argv)

    db = ensure_schema(sqlite3.connect(os.getenv("PORTAL_DB", "data/portal.sqlite")))
    try:
        if args.action == "import":
            report = import_dir(db, args.input_dir)
            report["release_version"] = release_version()
            print(json.dumps(report, ensure_ascii=False))
            return 0
        rows = query(db, args.channel, args.start, args.end, args.asof)
        print(json.dumps(rows, ensure_ascii=False))
        return 0
    except (ValueError, OSError, json.JSONDecodeError, sqlite3.Error) as problem:
        print(f"line.py {args.action} failed: {problem}", file=sys.stderr)
        return 2
    finally:
        db.close()


if __name__ == "__main__":
    sys.exit(main())
