def as_day(value):
    if value is None or value == "":
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    try:
        return date.fromisoformat(str(value).strip())
    except ValueError:
        raise ValueError(f"not a service day: {value!r}")


def parse_clock(value):
    if value is None:
        raise ValueError("missing clock")
    text = str(value).strip()
    for pattern in ("%H:%M:%S", "%H:%M"):
        try:
            return datetime.strptime(text, pattern).time()
        except ValueError:
            continue
    raise ValueError(f"not a clock time: {value!r}")


def channel_set(value):
    """`CD` / `C,D` / ['C','D'] -> {'C','D'}; None/empty -> None (all channels)."""
    if value is None or value == "":
        return None
    if isinstance(value, (list, tuple, set)):
        text = "".join(str(item) for item in value)
    else:
        text = str(value)
    letters = {char for char in text.upper() if char in CHANNEL_ALPHABET}
    return letters or None


def channel_in(channels, channel):
    if not channels:                        # authorisation covers every channel
        return True
    text = channels if isinstance(channels, str) else "".join(channels)
    return str(channel).upper() in text.upper()


